const $=s=>document.querySelector(s), esc=v=>String(v).replace(/[&<>'"]/g,c=>({ '&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'})[c]);
let selected=null;
async function json(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error();return r.json()}
async function render(){try{const feed=await json('/api/public/events'); $('#status-badge').textContent=feed.status; if(!selected||!feed.events.some(e=>e.id===selected))selected=feed.events[0]?.id; $('#event-tabs').innerHTML=feed.events.map(e=>`<button class="tab ${e.id===selected?'active':''}" data-id="${e.id}">${esc(e.name)}</button>`).join('');$('#event-tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=+b.dataset.id;render()});const event=feed.events.find(e=>e.id===selected);if(!event){$('#race-title').textContent='No published results';return}const rows=await json(`/api/public/events/${selected}/results`);$('#race-title').textContent=event.name;$('#result-count').textContent=`${rows.length} recorded riders`;$('#round-nav').innerHTML='';$('#stage-results').innerHTML=`<div class="race-grid single"><article class="race-table"><header><div><span>Live standings</span><h3>${esc(event.name)}</h3></div><b>${rows.length} riders</b></header><div class="table-scroll"><table><thead><tr><th>Pos</th><th>Rider</th><th>Time</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${i<3?'podium':''}"><td class="place">${r.position}</td><td><span class="rider"><span class="bib">${esc(r.bib)}</span><span class="name">${esc(r.name)}</span></span></td><td class="time">${esc(r.time)}</td></tr>`).join('')}</tbody></table></div></article></div>`}catch{$('#race-title').textContent='Waiting for timing feed';$('#result-count').textContent='The live results service is not connected yet.'}}
render();setInterval(render,15000);
